  {
    id = 'Progression__Tier_15_-_Tower_of_Frozen_Shadow',
    title = 'Tier 15 - Tower of Frozen Shadow',
    section = 'Progression',
    url = 'Progression/Tier_15_-_Tower_of_Frozen_Shadow.html',
    lines = {
    { k = 'h1', r = 'Progression - “Tower of Frozen Shadow”' },
    { k = 'gap' },
    { k = 'p', r = 'Tier 15 is built around the <b>Frozen Satchel</b>, a bag you upgrade from 10 slots all the way to the 50-slot <b>Mastercraft Frozen Satchel</b>. You upgrade it by crafting (safe) or by gambling (fast, but your bag can be destroyed). A hidden treasure waits for those who reach Mastercraft.' },
    { k = 'h2', r = 'Requirements' },
    { k = 'gap' },
    { k = 'li', r = 'To complete the tier: 1 <b>Mastercraft Frozen Satchel</b> (50 slots, Item #1011886) plus the hidden secret items.' },
    { k = 'li', r = 'You cannot loot the hidden items until you have completed at least 1 Mastercraft bag.' },
    { k = 'li', r = 'The tier flag unlocks only once you have both the bag and the secret items.' },
    { k = 'gap' },
    { k = 'h2', r = 'The NPCs' },
    { k = 'gap' },
    { k = 'li', r = '<b>Zone Guide</b> - hail for a popup with the full zone guide. Say a bag name (<i>frozen satchel</i>, <i>normal frozen</i>, <i>excellent frozen</i>, <i>superb frozen</i>, <i>mastercraft frozen</i>) to hear its item ID and slot count.' },
    { k = 'li', r = '<b>Frostbound Archivist</b> - riddle quest, starter kit, token exchange and the safe crafting upgrades.' },
    { k = 'li', r = '<b>The Gambler</b> (Mirror Room) - turns Vouchers into gambling credits and gambles your bags.' },
    { k = 'li', r = '<b>Aristotle\'s “smarter brother”</b> - sells Vouchers for AA points.' },
    { k = 'li', r = '<b>Zotro</b> - named by the guide as the source of your starter <b>Frozen Satchel</b> (10 slots).' },
    { k = 'gap' },
    { k = 'h2', r = 'Step 1 - The Frostbound Archivist\'s riddle' },
    { k = 'gap' },
    { k = 'p', r = 'Hail the <b>Frostbound Archivist</b> and follow the conversation:' },
    { k = 'li', r = '<i>Hail</i> - he asks what the ancient cipher [<b>means</b>].' },
    { k = 'li', r = '<i>means</i> - he recites the riddle and asks for the [<b>two methods</b>].' },
    { k = 'li', r = '<i>two methods</i> - choose the [<b>gambling path</b>], the [<b>crafting path</b>], or [<b>both</b>].' },
    { k = 'li', r = '<i>both</i> - he hints at a [<b>hidden treasure</b>].' },
    { k = 'li', r = '<i>hidden treasure</i> - he describes the ultra-rare hidden item and asks if you are [<b>ready</b>].' },
    { k = 'li', r = '<i>ready</i> - you receive the <b>Frozen Satchel Zone Guide</b> (Item #1011887) and 5 <b>Frozen Zone Tokens</b> (Item #1011888). <b>Once per character.</b>' },
    { k = 'gap' },
    { k = 'h2', r = 'Step 2 - Get Vouchers' },
    { k = 'gap' },
    { k = 'p', r = 'Vouchers (<b>Frozen Voucher</b>, Item #1011882) pay for crafting upgrades and gambling credits.' },
    { k = 'trh', cells = { 'Method', 'NPC', 'Cost', 'You get' } },
    { k = 'tr', cells = { 'Token exchange', '<b>Frostbound Archivist</b>', '4 <b>Frozen Zone Tokens</b> per voucher (hand in several sets at once)', '1 Voucher per 4 tokens + 500 exp per voucher' } },
    { k = 'tr', cells = { 'AA purchase', 'Aristotle\'s “smarter brother”', '25,000 AA points (say <i>buy Voucher</i>)', '1 Voucher' } },
    { k = 'gap' },
    { k = 'p', r = 'Frozen Zone Tokens drop from mobs in the zone. Named bosses have a higher token drop chance.' },
    { k = 'warn', r = '<b>Note:</b> Hand in tokens on their own. If you mix tokens with Vouchers, Leather or Runes, the Archivist gives everything back.' },
    { k = 'h2', r = 'Step 3a - The Crafter\'s Path (safe)' },
    { k = 'gap' },
    { k = 'p', r = 'Hand the materials to the <b>Frostbound Archivist</b>:' },
    { k = 'trh', cells = { 'Upgrade', 'Frozen Leather (#1011889)', 'Frozen Rune (#1011890)', 'Vouchers (#1011882)', 'Reward' } },
    { k = 'tr', cells = { '10 → 12 slots', '20', '-', '2', '<b>12-slot Frozen Satchel</b> (#1011891) + 2,000 exp' } },
    { k = 'tr', cells = { '12 → 15 slots', '30', '5', '5', '<b>15-slot Frozen Satchel</b> (#1011892) + 5,000 exp' } },
    { k = 'tr', cells = { '15 → 18 slots', '80', '10', '10', '<b>18-slot Frozen Satchel</b> (#1011893) + 10,000 exp' } },
    { k = 'gap' },
    { k = 'h2', r = 'Step 3b - The Gambler\'s Path (risky)' },
    { k = 'gap' },
    { k = 'li', r = 'Hail <b>The Gambler</b> and say <i>gamble</i> to see the options (<i>What is gambling here?</i>, <i>How do I gamble?</i>, <i>What are the odds?</i>, <i>Buy 1/5/10 Credits</i>).' },
    { k = 'li', r = 'Hand him <b>Frozen Vouchers</b>: each voucher becomes 1 gambling credit. Platinum is no longer accepted and is handed back.' },
    { k = 'li', r = 'Hand him 1 bag to gamble. Each roll uses 1 credit.' },
    { k = 'gap' },
    { k = 'p', r = 'Bags he accepts: <b>18-slot Frozen Satchel</b> (#1011893), <b>Normal Frozen Satchel</b> (#1011883, 20 slots), <b>Excellent Frozen Satchel</b> (#1011884, 30 slots), <b>Superb Frozen Satchel</b> (#1011885, 40 slots), <b>Mastercraft Frozen Satchel</b> (#1011886, 50 slots).' },
    { k = 'trh', cells = { 'Roll result', 'Chance', 'You receive' } },
    { k = 'tr', cells = { 'Normal', '30%', '<b>Normal Frozen Satchel</b> (20 slots)' } },
    { k = 'tr', cells = { 'Excellent', '25%', '<b>Excellent Frozen Satchel</b> (30 slots)' } },
    { k = 'tr', cells = { 'Superb', '15%', '<b>Superb Frozen Satchel</b> (40 slots)' } },
    { k = 'tr', cells = { 'Mastercraft', '5%', '<b>Mastercraft Frozen Satchel</b> (50 slots)' } },
    { k = 'tr', cells = { 'Destroyed', '25%', 'Nothing - the bag is lost' } },
    { k = 'gap' },
    { k = 'p', r = '<b>Important:</b> every roll uses the same odds no matter which bag you hand in. The result replaces your bag, so gambling a Superb can come back as a Normal. Wins and losses are announced zone-wide.' },
    { k = 'h2', r = 'The Hidden Treasure' },
    { k = 'gap' },
    { k = 'li', r = 'Requires: <b>Mastercraft Frozen Satchel</b> (50 slots).' },
    { k = 'li', r = 'Location: the deepest ice cave.' },
    { k = 'li', r = 'Hint 1: look for see-invis walls.' },
    { k = 'li', r = 'Hint 2: solve the 4 Frozen Runes puzzle (the order is in an ancient tome).' },
    { k = 'li', r = 'Hint 3: the hidden chest requires a 50-slot bag to loot.' },
    { k = 'li', r = 'Reward: a powerful legendary clicky.' },
    { k = 'gap' },
    { k = 'h2', r = 'Item reference' },
    { k = 'gap' },
    { k = 'trh', cells = { 'Item', 'ID' } },
    { k = 'tr', cells = { '<b>Frozen Voucher</b>', '1011882' } },
    { k = 'tr', cells = { '<b>Normal Frozen Satchel</b> (20)', '1011883' } },
    { k = 'tr', cells = { '<b>Excellent Frozen Satchel</b> (30)', '1011884' } },
    { k = 'tr', cells = { '<b>Superb Frozen Satchel</b> (40)', '1011885' } },
    { k = 'tr', cells = { '<b>Mastercraft Frozen Satchel</b> (50)', '1011886' } },
    { k = 'tr', cells = { '<b>Frozen Satchel Zone Guide</b>', '1011887' } },
    { k = 'tr', cells = { '<b>Frozen Zone Token</b>', '1011888' } },
    { k = 'tr', cells = { '<b>Frozen Leather</b>', '1011889' } },
    { k = 'tr', cells = { '<b>Frozen Rune</b>', '1011890' } },
    { k = 'tr', cells = { '<b>12 / 15 / 18-slot Frozen Satchel</b>', '1011891 / 1011892 / 1011893' } },
    { k = 'gap' },
    },
