  {
    id = 'Items__Prestige_Items_and_How_To',
    title = 'Howto obtain Prestige Items',
    section = 'Items',
    url = 'Items/Prestige_Items_and_How_To.html',
    lines = {
    { k = 'p', r = 'First thing to note is that when upgrading your charm you do NOT receive reaping points.... Reaping points can only be obtained by deleveling for the purpose of AA points only!' },
    { k = 'p', r = 'You will be unable to purchase <b>Rk. 1 Necklace</b> after relevelling to level 70.' },
    { k = 'p', r = 'To begin the process locate <b>Reaper</b> in Plane of Knowledge or Nexus and hail him/her/it. He will ask if you would like to earn some additional AA Points, you will need to follow this prompt. At the end of the prompt he will ask if you are ready to Delevel, You will lose all 69 levels and no longer have access to most gear stats unless you have pre-farmed for them. You WILL have access to your item clickys IE Dmg shield from cloak, so make sure to use them to your advantage. <b>Note</b> This is the ONLY way to achieve reaper points currently.' },
    { k = 'p', r = 'Completing this process 200x will reward <b>Rk. 200</b>' },
    { k = 'p', r = 'When you delevel, you lose all of your buffs including the Exp buff. Plan accordingly!!!' },
    { k = 'p', r = 'Good luck, Any questions feel free to message me in game on Skeezi' },
    },
  },
