    { k = 'p', r = 'The Astrial Infuse quest was introduced 3/28/2020.' },
    { k = 'p', r = 'Enine posted the following information on Discord:' },
    { k = 'warn', r = 'The first edition of the Astrial Aug has been released speak to Astrial infuse inside of Temple of Veeshan for information of obtaining it. Let it be known this will not be a walk in the park farm for these items they will take effect. Once the weapon is fully completed by a player then Timekeeper Credits weapons will have a increase in power as well. I will work on implementing the next 2 editions and the final combine today or tomorrow. (Updated: 4/9/2020) All Astrial Item\'s have been added in. Every tier zone requires items from ToV to Xorbb. From ToV to Najena you will make augs to fit inside them. From the Hole to Xorbb you will need a book from each tier. A final combine will be finished here soon once I make them all to create your new Astrial weapon.' },
    { k = 'label', r = 'Collect:' },
    { k = 'p', r = '<b>Bottom Splinter of Astrial </b>' },
    { k = 'p', r = '<b>Center Splinter of Astrial </b>' },
    { k = 'p', r = '<b>Left Splinter of Astrial </b>' },
    { k = 'p', r = '<b>Right Splinter of Astrial </b>' },
    { k = 'p', r = '<b>Top Splinter of Astrial </b>' },
    { k = 'p', r = 'Combine these items in Plane of Knowledge using a Forge.' },
    { k = 'label', r = 'Reward:' },
    { k = 'p', r = '<b>Astrial\'s Major Infuse</b>' },
    },
  },
  {
    id = 'Items_Astrial__Astrial_Weapon',
    title = 'Astrial Weapon',
    section = 'Astrial',
    url = 'Items_Astrial/Astrial_Weapon.html',
    lines = {
    { k = 'h3', r = 'Part One' },
    { k = 'gap' },
    { k = 'p', r = 'Quest begins with <b>Astrial Messenger</b> found in the south wing of the Nexus. You will need 4 items for the initial quest. The items are not NO DROP.' },
    { k = 'li', r = 'Strongest Carapace- <b>Shell of Lodizal</b> (Looks like turtle shell) from Lodizal in Iceclad. Don\'t confuse this with <b>Section of Lodizal\'s Shell</b>. Not a guaranteed drop, so you may have to kill a few times.' },
    { k = 'li', r = 'Fire from the hottest forge- <b>Everburning Flame</b> Ground spawn behind King Tranix in Soldungb.' },
    { k = 'li', r = 'Piece of Living Rock- <b>Beating Heart of Earth</b> Drops from the Avatar of Earth in poearthb. This event is live so you must kill the 12 councilmen to spawn avatar of earth. Not a guaranteed drop, so you may have to kill a few times. The event is on a respawn timer of about 1 hour.' },
    { k = 'li', r = '<b>Piece of your soul</b> in agony - you must die to the Avatar of Agony in Plane of Torment DO NOT DIE TO THE ADDS or you will not get credit! This mob has placeholders and the respawn is 30 minutes. This item is also No Trade!' },
    { k = 'gap' },
    { k = 'p', r = 'Turn in the 4 items to Astrial in order to Astrial Messenger! Hail him/her to make sure what item is required before turning in!' },
    { k = 'warn', r = '<b>NOTE: You can only possess ONE Astrial weapon. You cannot dual wield Astrials.</b>' },
    { k = 'h3', r = 'Part Two' },
    { k = 'gap' },
    { k = 'p', r = 'Now the fun begins. The Astrial Messenger tells you to hand him: <b>Dragon Sprit Core x 50</b>, 1 Unfinished Weapon, 1 <b>Combined Fallen Star</b>, and 1 <b>Astrial Mist</b>' },
    { k = 'p', r = 'You will need the following:' },
    { k = 'p', r = '1 <b>Astrial Mist</b> - (Global Drop) Rare' },
    { k = 'cmd', r = '- Astrial Mist drops from undead mobs. You may have better luck getting one from Kurns Tower.' },
    { k = 'li', r = '3 <b>Celestial Ingots</b> (Global Drop) Ultra Rare' },
    { k = 'li', r = '1 <b>Hermits Lost Anvil</b> (Global Drop) Rare' },
    { k = 'li', r = '1 <b>Ancient Runes</b> (Global Drop) Rare' },
    { k = 'li', r = '1 <b>Hermits Lost Chisel</b> (Global Drop) Rare' },
    { k = 'li', r = '1 <b>celestial Temper</b> (Global Drop - not the crafted version)' },
    { k = 'li', r = '1 <b>Hermits lost Forging Hammer</b> (Global Drop) Rare' },
    { k = 'li', r = '6 <b>Fallen Star</b> (Global Drop) Ultra Rare - Chance of Combine Fail recommend at least 12 if not 18.' },
    { k = 'li', r = '1 <b>Elemental Infused Elixir</b> (Global Drop) Rare' },
    { k = 'li', r = '100 <b>Minor Dragon Spirit</b> (Temple of Veeshan- Tier 1) Rare - Chance of Combine Fails recommend at least 126+' },
    { k = 'li', r = '2000 AA Points' },
    { k = 'li', r = '125,000 Platinum' },
    { k = 'gap' },
    { k = 'p', r = 'Suggested Additional Items' },
    { k = 'li', r = '<b>Geerlok Gem Setter</b> - Comes from Tinkering and adds +5% mod to Jewelry Crafting (15 point max). Helpful when combining Fallen Stars.' },
    { k = 'li', r = '<b>Umbracite Swarm Orb</b> - This <i>dropped</i> item is from Vex Thal off of Diabo Xi Va Temariel and adds a whopping 15% to your alchemy skill (45 point max).' },
    { k = 'gap' },
    { k = 'h3', r = 'Making the unfinished weapon' },
    { k = 'gap' },
    { k = 'li', r = 'First -You will need to purchase a mold from <b>a hermit</b> in southkarana to do so you will need 2000 AA Points (NOT TOKENS) and roughly 100,000 Platinum (Unsure at this time if price changes based on type of weapon). <b>You will need to hail him repeatedly until he talks to you</b>.' },
    { k = 'li', r = 'Second- You will need (3) celestial Ingots, (1) hermits lost anvil, (1) Ancient Runes, (1) hermits lost chisel, (1) Hermits lost forging hammer, (1) Elemental Infused Elixer and (1) celestial Temper (this item is a DROP not crafted version).' },
    { k = 'li', r = 'Third- You will need to take the 9 items (Listed above) and the Mold of your choice (Listed Above) and go to 10 slot forge in PoKnowledge next to Caden Zharik. Reminder DO NOT STACK THE CELESTIAL INGOTS INSIDE OF FORGE!' },
    { k = 'li', r = 'Fourth- Combine all items inside of forge. (Update 7/16 - This combine seems to be 0 Trivial, so should be no-fail).' },
    { k = 'li', r = 'You should have completed the combine of whatever mold you picked. Your weapon should have Hollow in name will look like junk, DO NOT DESTROY!' },
    { k = 'gap' },
    { k = 'h3', r = 'Making the Dragon Spirit Cores' },
    { k = 'gap' },
    { k = 'li', r = 'You will need to combine (2) Minor Dragon Spirit inside of an Alchemy Bag.' },
    { k = 'li', r = 'To make <b>Dragon Spirit Cores</b> you will need a shaman with max alchemy and Tinkering tool to increase skill to 315, this seems to actually affect the failure rate. You will need to Experiment on the first combine to learn the recipe. After that you can simply combine and auto inventory item.' },
    { k = 'gap' },
    { k = 'h3', r = 'Making the Combined Star' },
    { k = 'gap' },
    { k = 'p', r = 'Suggestion : Pickup a tinkering tool to increase Jewelry Crafting by 15 points as this will be your most expensive failure.' },
    { k = 'li', r = 'To combine the Fallen stars you will need to pick up a &quot;Planar Jewelry Kit&quot; (6) Slots. Put 6 <b>Fallen Stars</b> (Unstacked) in Planer Jewelry Kit and Combine them.' },
    { k = 'gap' },
    { k = 'h3', r = 'Astrial Mist' },
    { k = 'gap' },
    { k = 'p', r = 'This is a global drop seems exceptionally rare. Good luck!' },
    { k = 'cmd', r = '- In case you didn\'t read up above – Astrial Mist drops from undead mobs' },
    { k = 'h3', r = 'The Final Turn In' },
    { k = 'gap' },
    { k = 'p', r = 'The Astrial Messenger says he wants 50 x <b>Dragon Spirit Cores</b>, but if you turn in a stack of 50 you will lose them (I learned this the hard way). You can hail him until he says that he will auto import all cores from your inventory at once. You can also hand him the Dragon Spirit Cores 1-by-1 until you have given him 50. I would just let him auto import all cores from your inventory to avoid any turn in issues. Then you can hail him and he\'ll give you the <b>Completed Dragon Spirit Core.</b>' },
    { k = 'p', r = 'Hand in all 4 items (<b>Completed Dragon Spirit Core</b>, 1 Unfinished Weapon, 1 <b>Combined Fallen Star</b>, and 1 <b>Astrial Mist</b>) to receive your weapon.' },
    { k = 'h3', r = 'Final Weapon' },
    { k = 'gap' },
    { k = 'p', r = 'There are several variants of the weapon available. The weapon you get depends on the mold you buy from the hermit.' },
    { k = 'li', r = '<b>Marvelous Astrial Blade</b> - 1HS' },
    { k = 'li', r = '<b>Marvelous Astrial Bow</b> - Ranged' },
    { k = 'li', r = '<b>Marvelous Astrial Dagger</b> - Piercing' },
    { k = 'li', r = '<b>Marvelous Astrial Great Axe</b> - 2HS' },
    { k = 'li', r = '<b>Marvelous Astrial Great Staff</b> - 2HB' },
    { k = 'li', r = '<b>Marvelous Astrial Knuckles</b> - Martial' },
    { k = 'li', r = '<b>Marvelous Astrial Mace</b> - 1HB' },
    { k = 'li', r = '<b>Marvelous Astrial Spear</b> - 2H Piercing' },
    { k = 'li', r = '<b>Marvelous Astrial Wand</b> - 1HB' },
    { k = 'gap' },
    { k = 'h3', r = 'Augments' },
    { k = 'gap' },
    { k = 'p', r = 'The Astrial weapons have unique augment slots that have specific Astrial ONLY augments acquired by the quests below.' },
    { k = 'p', r = '<b>Astrial\'s Infuse</b> (Aug #1 - Slot 2, Type 22)' },
    { k = 'cmd', r = '- The bits to make this aug are from [Temple of Veeshan](/Tier_1_Progression_-_Temple_of_Veeshan)' },
    { k = 'p', r = '<b>Astrial\'s Greater Infuse</b> (Aug #2 - Slot 3, Type 23)' },
    { k = 'cmd', r = '- The bits to make this aug are from [Riftseekers](/Tier_2_Gear_-_Riftseekers\'_Sanctum).' },
    { k = 'p', r = '<b>Astrial\'s Major Infuse</b> (Aug #3 - Slot 4, Type 24)' },
    { k = 'cmd', r = '- The bits to make this aug are from [Najena](/Tier_3_Gear_-_Najena).' },
    { k = 'h3', r = 'Astrial Weapon 2.0' },
    { k = 'gap' },
    { k = 'warn', r = '<b>WARNING - If you take your Astrial weapon to the 2.0 version you can not exchange it at the vendor anymore.</b>' },
    { k = 'p', r = 'You will need to collect the following books.' },
    { k = 'li', r = '<b>Book of Astrial-1</b> - From - The Hole' },
    { k = 'li', r = '<b>Book of Astrial-2</b> - From - MPG' },
    { k = 'li', r = '<b>Book of Astrial-3</b> - From - Kael' },
    { k = 'li', r = '<b>Book of Astrial-4</b> - From - Anguish' },
    { k = 'li', r = '<b>Book of Astrial-5</b> - From - Sleeper' },
    { k = 'li', r = '<b>Book of Astrial-6</b> - From - Xorbb' },
    { k = 'gap' },
    { k = 'p', r = 'On top of that you will need to make a <b>Tome of Astrial</b>' },
    { k = 'p', r = 'Combine the 3 augments in a Universal Assembly Crate to make a Tome of Astrial.' },
    { k = 'li', r = 'Astrial\'s Infuse' },
    { k = 'li', r = 'Astrial\'s Greater Infuse' },
    { k = 'li', r = 'Astrial\'s Major Infuse' },
    { k = 'gap' },
    { k = 'p', r = 'After you have the 6 Books of Astrial and the Tome of Astrial -' },
    { k = 'li', r = 'Combine all 6 Books + Tome + Astrial 1.0 in a Universal Assembly Crate to create the Astrial 2.0' },
    { k = 'gap' },
    },
