  {
    id = 'Macroquest__MacroHelp_EQ_Built-in_Macros',
    title = 'Everquest Build-in Macro System',
    section = 'MacroQuest',
    url = 'Macroquest/MacroHelp_EQ_Built-in_Macros.html',
    lines = {
    { k = 'p', r = 'Repository for some useful macros using the built-in feature. While not as robust as MQ2, there is still plenty of functionality.' },
    { k = 'h2', r = 'The Basics' },
    { k = 'gap' },
    { k = 'p', r = 'I\'ll assume that everyone is familiar with creating a macro. If not, there are several resources available online. I found this one to be pretty comprehensive:' },
    { k = 'p', r = 'There are too many commands to list, so I\'ve concentrated on some useful ones here. You can see a full list of commands in game with the /help command.' },
    { k = 'p', r = 'You can add up to 5 lines of commands per macro. One command per line except that /pause and /timer can be added to the same line as another command.' },
    { k = 'h2', r = 'Combining /pause and /timer Commands' },
    { k = 'gap' },
    { k = 'p', r = '/pause and /timer are the only commands that can be added to the same line as another command. They must be added first and followed by a comma.' },
    { k = 'p', r = '/pause 30, /cast 1' },
    { k = 'h2', r = 'Useful Commands' },
    { k = 'gap' },
    { k = 'p', r = '/Pause - Pause in between commands. 1 second == 10 units. /Timer - Set a visible reset timer for the macro. 1 second == 10 units /UseItem - Click an item in your inventory. /Cast - Cast a spell from a memorized slot.' },
    { k = 'h2', r = 'Examples' },
    { k = 'gap' },
    { k = 'p', r = '<b>Cuddly Bear of Mass Rage</b>' },
    { k = 'li', r = 'Start a 5 minute timer after clicking. You can click for free as many times as you want during this 5 minutes. This example has the bear in the bottom right slot of the bottom right inventory bag.' },
    { k = 'gap' },
    { k = 'p', r = '/timer 3000, /useitem 32 9' },
    },
  },
