 class="code">[group]</span> {{save FormName', 'load FormName}} <span class="code">[zone]</span> {{chrush', 'unrest', 'gubk', 'seb', 'solr', 'cod', 'pofi', 'tov', 'rift', 'hn', 'hole', 'mpg', 'keal', 'angu', 'sleep', 'xorbb', 'devast}} <span class="code">[loot]</span> {{all', 'force', 'Ignore,Sell,Keep,Destroy,quest,auto,common,notify}} <span class="code">[warp]</span> <span class="code">[eq]</span> {{sound mute/value', 'effect on/off', 'fg value', 'bg value', '}} <span class="code">[lps]</span> {{on', 'off}} <span class="code">[exit]</span> <span class="code">[camp]</span> <span class="code">[start', 'restart', 'end]</span>' } },
